async def handle_online_stock_search(request):
    """Searches online stock (Pexels) with automatic zero-reuse filtering (ADR-009)."""
    query = request.query.get("query", "").strip()
    page = int(request.query.get("page", 1))
    per_page = int(request.query.get("per_page", 12))

    if not query:
        return web.json_response({"status": "ok", "videos": [], "total_results": 0})

    try:
        client = PexelsClient()
        loop = asyncio.get_event_loop()
        res = await loop.run_in_executor(None, lambda: client.search_videos(query=query, page=page, per_page=per_page))
        return web.json_response(res)
    except Exception as e:
        return web.json_response({"status": "error", "message": f"Lá»—i tÃ¬m kiáº¿m online stock: {e}"}, status=500)

